import{_ as e,C as t,c as i,o as a,j as o,G as n,a0 as r,b as s,a as l,w as u,a1 as c}from"./chunks/framework.DKRgXLPU.js";const h=JSON.parse('{"title":"Session Guide: Mental Game Introduction (2-3 Hours)","description":"","frontmatter":{},"headers":[],"relativePath":"en/mental-journey/session-guide.md","filePath":"en/mental-journey/session-guide.md"}');const p=e({name:"en/mental-journey/session-guide.md"},[["render",function(e,h,p,d,g,m){const f=t("AdBanner"),y=t("Mermaid"),q=t("AdInArticle");return a(),i("div",null,[h[1]||(h[1]=o("h1",{id:"session-guide-mental-game-introduction-2-3-hours",tabindex:"-1"},[l("Session Guide: Mental Game Introduction (2-3 Hours) "),o("a",{class:"header-anchor",href:"#session-guide-mental-game-introduction-2-3-hours","aria-label":'Permalink to "Session Guide: Mental Game Introduction (2-3 Hours)"'},"​")],-1)),n(f),h[2]||(h[2]=r('<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This guide helps you conduct a 2-3 hour introductory session on mental game training for pétanque players. Perfect for coaches, club leaders, or experienced players who want to introduce mental training to their team.</p><div class="tip custom-block"><p class="custom-block-title">Two Sections in This Guide</p><ul><li><strong><a href="#for-participants">For Participants</a></strong> - What players will learn</li><li><strong><a href="#for-facilitators">For Facilitators</a></strong> - How to conduct the session</li></ul></div><h2 id="quick-access" tabindex="-1">Quick Access <a class="header-anchor" href="#quick-access" aria-label="Permalink to &quot;Quick Access&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Purpose</th><th>Access</th></tr></thead><tbody><tr><td><strong>For Participants</strong></td><td>What to expect from the session</td><td><a href="#for-participants">View Section</a></td></tr><tr><td><strong>For Facilitators</strong></td><td>Complete session plan and timing</td><td><a href="#for-facilitators">View Section</a></td></tr><tr><td><strong>Session Materials</strong></td><td>Guides, slides, and worksheets</td><td><a href="/en/mental-journey/materials">View Materials</a></td></tr><tr><td><strong>Preparation Checklist</strong></td><td>What to prepare before the session</td><td><a href="#preparation-1-week-before">View Checklist</a></td></tr></tbody></table><hr><h2 id="for-participants" tabindex="-1">For Participants <a class="header-anchor" href="#for-participants" aria-label="Permalink to &quot;For Participants&quot;">​</a></h2><h3 id="what-to-expect" tabindex="-1">What to Expect <a class="header-anchor" href="#what-to-expect" aria-label="Permalink to &quot;What to Expect&quot;">​</a></h3><p>This session introduces the mental game of pétanque through discussion, exercises, and practical techniques you can use immediately.</p><p><strong>You&#39;ll Learn:</strong></p><ul><li>Why mental training matters for performance</li><li>The difference between &quot;technical mode&quot; and &quot;flow mode&quot;</li><li>How to recognize and manage your inner critic</li><li>Simple techniques for pressure management</li><li>A basic pre-shot routine</li></ul><p><strong>What You&#39;ll Need:</strong></p><ul><li>Open mind and willingness to share</li><li>Notebook and pen</li><li>Your own experiences to discuss</li><li>2-3 hours of focused time</li></ul><h3 id="session-structure" tabindex="-1">Session Structure <a class="header-anchor" href="#session-structure" aria-label="Permalink to &quot;Session Structure&quot;">​</a></h3>',14)),(a(),s(c,null,{default:u(()=>[n(y,{id:"mermaid-157",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BIntroduction%3Cbr%2F%3E20%20min%5D%20--%3E%20B%5BThe%20Zone%3Cbr%2F%3E40%20min%5D%0A%20%20%20%20B%20--%3E%20C%5BBreak%3Cbr%2F%3E10%20min%5D%0A%20%20%20%20C%20--%3E%20D%5BInner%20Critic%3Cbr%2F%3E40%20min%5D%0A%20%20%20%20D%20--%3E%20E%5BPractical%20Tools%3Cbr%2F%3E40%20min%5D%0A%20%20%20%20E%20--%3E%20F%5BIntegration%3Cbr%2F%3E20%20min%5D%0A%20%20%20%20%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23f3e5f5%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23c8e6c9%0A"})]),fallback:u(()=>[...h[0]||(h[0]=[l(" Loading... ",-1)])]),_:1})),h[3]||(h[3]=r('<h3 id="key-concepts-you-ll-explore" tabindex="-1">Key Concepts You&#39;ll Explore <a class="header-anchor" href="#key-concepts-you-ll-explore" aria-label="Permalink to &quot;Key Concepts You&#39;ll Explore&quot;">​</a></h3><h4 id="_1-the-zone-flow-state" tabindex="-1">1. The Zone (Flow State) <a class="header-anchor" href="#_1-the-zone-flow-state" aria-label="Permalink to &quot;1. The Zone (Flow State)&quot;">​</a></h4><ul><li>What it feels like when everything clicks</li><li>Why thinking about technique disrupts performance</li><li>The &quot;switch&quot; from planning to execution</li></ul><h4 id="_2-the-inner-critic" tabindex="-1">2. The Inner Critic <a class="header-anchor" href="#_2-the-inner-critic" aria-label="Permalink to &quot;2. The Inner Critic&quot;">​</a></h4><ul><li>How negative self-talk affects performance</li><li>The difference between Inner Critic and Inner Coach</li><li>Neutral observation vs harsh judgment</li></ul><h4 id="_3-pressure-response" tabindex="-1">3. Pressure Response <a class="header-anchor" href="#_3-pressure-response" aria-label="Permalink to &quot;3. Pressure Response&quot;">​</a></h4><ul><li>Why you play differently in competition</li><li>Physical signs of pressure</li><li>Quick reset techniques</li></ul><h4 id="_4-practical-tools" tabindex="-1">4. Practical Tools <a class="header-anchor" href="#_4-practical-tools" aria-label="Permalink to &quot;4. Practical Tools&quot;">​</a></h4><ul><li>3-breath reset</li><li>Simple pre-shot routine</li><li>Mistake recovery protocol</li></ul><h3 id="what-to-bring" tabindex="-1">What to Bring <a class="header-anchor" href="#what-to-bring" aria-label="Permalink to &quot;What to Bring&quot;">​</a></h3><p><strong>Required:</strong></p><ul><li>Yourself and your experiences</li><li>Willingness to participate</li></ul><p><strong>Optional:</strong></p><ul><li>Examples of mental challenges you face</li><li>Questions about specific situations</li><li>Notebook for personal notes</li></ul><h3 id="after-the-session" tabindex="-1">After the Session <a class="header-anchor" href="#after-the-session" aria-label="Permalink to &quot;After the Session&quot;">​</a></h3><p>You&#39;ll receive:</p><ul><li>Summary handout of key concepts</li><li>Practice exercises for the week</li><li>Links to detailed education modules</li><li>Goal template for mental game development</li></ul>',17)),n(q),h[4]||(h[4]=r('<hr><h2 id="for-facilitators" tabindex="-1">For Facilitators <a class="header-anchor" href="#for-facilitators" aria-label="Permalink to &quot;For Facilitators&quot;">​</a></h2><h3 id="preparation-checklist" tabindex="-1">Preparation Checklist <a class="header-anchor" href="#preparation-checklist" aria-label="Permalink to &quot;Preparation Checklist&quot;">​</a></h3><p><strong>1 Week Before:</strong></p><ul><li>[ ] Book room for 2-3 hours</li><li>[ ] Invite 6-12 participants</li><li>[ ] Bookmark materials pages (see <a href="/en/mental-journey/materials">Materials</a>)</li><li>[ ] Review this guide thoroughly</li><li>[ ] Prepare flip chart or whiteboard</li></ul><p><strong>1 Day Before:</strong></p><ul><li>[ ] Confirm attendance</li><li>[ ] Set up room (circle seating)</li><li>[ ] Test any technology (slides, etc.)</li><li>[ ] Prepare materials</li></ul><p><strong>1 Hour Before:</strong></p><ul><li>[ ] Arrive early</li><li>[ ] Arrange seating in circle</li><li>[ ] Set up materials</li><li>[ ] Center yourself</li></ul><h3 id="your-role-as-facilitator" tabindex="-1">Your Role as Facilitator <a class="header-anchor" href="#your-role-as-facilitator" aria-label="Permalink to &quot;Your Role as Facilitator&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Important</p><p>You are <strong>not</strong> a therapist or technical coach. You are a <strong>facilitator</strong> who:</p><ul><li>Guides discussion</li><li>Creates safe space</li><li>Connects concepts to experience</li><li>Manages group dynamics</li></ul></div><p><strong>Key Skills:</strong></p><ul><li>Active listening</li><li>Neutral presence</li><li>Managing different personalities</li><li>Knowing when to move on</li></ul><h3 id="detailed-session-plan" tabindex="-1">Detailed Session Plan <a class="header-anchor" href="#detailed-session-plan" aria-label="Permalink to &quot;Detailed Session Plan&quot;">​</a></h3><hr><h4 id="part-1-introduction-20-minutes" tabindex="-1">Part 1: Introduction (20 minutes) <a class="header-anchor" href="#part-1-introduction-20-minutes" aria-label="Permalink to &quot;Part 1: Introduction (20 minutes)&quot;">​</a></h4><p><strong>Objectives:</strong></p><ul><li>Create psychological safety</li><li>Set expectations</li><li>Build group connection</li></ul><p><strong>Script:</strong></p><p>&quot;Welcome everyone. This session is about the mental game of pétanque - the thoughts, feelings, and patterns that affect your performance.</p><p><strong>Ground Rules:</strong></p><ol><li>What&#39;s shared here stays here</li><li>No judgment of others&#39; experiences</li><li>Participation is voluntary</li><li>There are no wrong answers</li></ol><p><strong>Quick Round:</strong> Name, how long you&#39;ve played, one mental challenge you face.&quot;</p><p><strong>Facilitator Notes:</strong></p><ul><li>Go first to model vulnerability</li><li>Keep introductions brief (1 min each)</li><li>Notice common themes</li><li>Validate all responses</li></ul><hr><h4 id="part-2-the-zone-flow-state-40-minutes" tabindex="-1">Part 2: The Zone / Flow State (40 minutes) <a class="header-anchor" href="#part-2-the-zone-flow-state-40-minutes" aria-label="Permalink to &quot;Part 2: The Zone / Flow State (40 minutes)&quot;">​</a></h4><p><strong>Objectives:</strong></p><ul><li>Understand flow states</li><li>Recognize technical vs flow mode</li><li>Learn the &quot;switch&quot; concept</li></ul><p><strong>Opening Question:</strong> &quot;Think of a time when you played your best pétanque. What did it feel like? What was different?&quot;</p><p><strong>Discussion Prompts:</strong></p><ol><li>&quot;How many of you have had games where everything just clicked?&quot;</li><li>&quot;What were you thinking about during those moments?&quot;</li><li>&quot;How is that different from when you struggle?&quot;</li></ol><p><strong>Key Teaching Points:</strong></p><p>Use whiteboard to draw:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PLANNING MODE          →    EXECUTION MODE</span></span>\n<span class="line"><span>(Outside circle)            (Inside circle)</span></span>\n<span class="line"><span>- Analyze situation         - Eyes on target</span></span>\n<span class="line"><span>- Choose strategy           - Trust training</span></span>\n<span class="line"><span>- Decide throw type         - Automatic movement</span></span></code></pre></div><p><strong>Exercise: The Switch (10 minutes)</strong></p><p>&quot;Let&#39;s practice the switch moment:</p><ol><li>Stand up</li><li>Imagine you&#39;re outside the circle - think about a shot</li><li>Take a breath</li><li>Step forward (into imaginary circle)</li><li>As you step, let go of analysis</li><li>Focus only on an imaginary target&quot;</li></ol><p><strong>Debrief:</strong></p><ul><li>&quot;What did you notice?&quot;</li><li>&quot;Was it easy or hard to let go of thinking?&quot;</li><li>&quot;How might this apply in real games?&quot;</li></ul><hr><h4 id="part-3-break-10-minutes" tabindex="-1">Part 3: Break (10 minutes) <a class="header-anchor" href="#part-3-break-10-minutes" aria-label="Permalink to &quot;Part 3: Break (10 minutes)&quot;">​</a></h4><p><strong>Facilitator Actions:</strong></p><ul><li>Encourage informal discussion</li><li>Notice group energy</li><li>Prepare for next section</li></ul><hr><h4 id="part-4-the-inner-critic-40-minutes" tabindex="-1">Part 4: The Inner Critic (40 minutes) <a class="header-anchor" href="#part-4-the-inner-critic-40-minutes" aria-label="Permalink to &quot;Part 4: The Inner Critic (40 minutes)&quot;">​</a></h4><p><strong>Objectives:</strong></p><ul><li>Recognize negative self-talk patterns</li><li>Distinguish Inner Critic from Inner Coach</li><li>Practice neutral observation</li></ul><p><strong>Opening:</strong> &quot;We all have an inner voice that comments on our performance. Sometimes it&#39;s helpful, sometimes it&#39;s harsh. Let&#39;s explore that.&quot;</p><p><strong>Exercise: Inner Critic Inventory (15 minutes)</strong></p><p>&quot;On your paper, write down:</p><ol><li>What your inner voice says after a bad throw</li><li>What it says when you&#39;re under pressure</li><li>What it says about your abilities&quot;</li></ol><p><em>Give 5 minutes for writing</em></p><p>&quot;Now, who&#39;s willing to share one example?&quot;</p><p><strong>Facilitator Notes:</strong></p><ul><li>Normalize harsh self-talk</li><li>Don&#39;t try to &quot;fix&quot; anyone</li><li>Look for common patterns</li></ul><p><strong>Teaching: Inner Critic vs Inner Coach (15 minutes)</strong></p><p>Draw two columns on whiteboard:</p><table tabindex="0"><thead><tr><th>Inner Critic</th><th>Inner Coach</th></tr></thead><tbody><tr><td>&quot;How could you miss that?!&quot;</td><td>&quot;That went left&quot;</td></tr><tr><td>&quot;You always choke&quot;</td><td>&quot;Let&#39;s try again&quot;</td></tr><tr><td>&quot;You&#39;re terrible&quot;</td><td>&quot;What can I learn?&quot;</td></tr></tbody></table><p><strong>Discussion:</strong></p><ul><li>&quot;Notice the difference?&quot;</li><li>&quot;Which voice helps performance?&quot;</li><li>&quot;Can you change the voice?&quot;</li></ul><p><strong>Practice: Reframing (10 minutes)</strong></p><p>&quot;Take one of your Inner Critic statements. How would an Inner Coach say it?&quot;</p><p>Share examples.</p><hr><h4 id="part-5-practical-tools-40-minutes" tabindex="-1">Part 5: Practical Tools (40 minutes) <a class="header-anchor" href="#part-5-practical-tools-40-minutes" aria-label="Permalink to &quot;Part 5: Practical Tools (40 minutes)&quot;">​</a></h4><p><strong>Objectives:</strong></p><ul><li>Learn 3-breath reset</li><li>Create simple pre-shot routine</li><li>Understand mistake recovery</li></ul><p><strong>Tool 1: 3-Breath Reset (10 minutes)</strong></p><p>&quot;This is your emergency reset button. Use it when you feel pressure building.&quot;</p><p><strong>Demonstrate:</strong></p><ol><li>Breathe in for 4 counts</li><li>Hold for 2 counts</li><li>Breathe out for 6 counts</li><li>Repeat 3 times</li></ol><p>&quot;Let&#39;s practice together now.&quot;</p><p><em>Lead the group through 3 cycles</em></p><p><strong>Debrief:</strong></p><ul><li>&quot;What did you notice in your body?&quot;</li><li>&quot;When might you use this?&quot;</li></ul><p><strong>Tool 2: Simple Pre-Shot Routine (15 minutes)</strong></p><p>&quot;A routine helps you switch from planning to execution consistently.&quot;</p><p><strong>Basic Structure:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Outside Circle (Planning):</span></span>\n<span class="line"><span>- Look at situation</span></span>\n<span class="line"><span>- Decide on throw</span></span>\n<span class="line"><span>- See the result in your mind</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Walking to Circle (Transition):</span></span>\n<span class="line"><span>- One deep breath</span></span>\n<span class="line"><span>- Let go of analysis</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Inside Circle (Execution):</span></span>\n<span class="line"><span>- Eyes on target only</span></span>\n<span class="line"><span>- Trust your training</span></span>\n<span class="line"><span>- Execute</span></span></code></pre></div><p><strong>Exercise:</strong> &quot;Create your own 3-step routine. Write it down.&quot;</p><p>Share examples.</p><p><strong>Tool 3: Mistake Recovery Protocol (15 minutes)</strong></p><p>&quot;Elite players don&#39;t make fewer mistakes. They recover faster.&quot;</p><p><strong>3-Step Protocol:</strong></p><ol><li><strong>Observe</strong> - State the fact neutrally (&quot;That went left&quot;)</li><li><strong>Learn</strong> - Extract information (&quot;Wind stronger than I thought&quot;)</li><li><strong>Reset</strong> - Move forward (3-breath reset, eyes forward)</li></ol><p><strong>Practice:</strong> &quot;Think of a recent mistake. Walk through the 3 steps.&quot;</p><hr><h4 id="part-6-integration-closing-20-minutes" tabindex="-1">Part 6: Integration &amp; Closing (20 minutes) <a class="header-anchor" href="#part-6-integration-closing-20-minutes" aria-label="Permalink to &quot;Part 6: Integration &amp; Closing (20 minutes)&quot;">​</a></h4><p><strong>Objectives:</strong></p><ul><li>Consolidate learning</li><li>Create action plans</li><li>Provide resources</li></ul><p><strong>Reflection Questions:</strong></p><ol><li>&quot;What&#39;s one insight you&#39;re taking away?&quot;</li><li>&quot;What&#39;s one thing you&#39;ll try this week?&quot;</li><li>&quot;What questions remain?&quot;</li></ol><p><strong>Action Planning (10 minutes)</strong></p><p>&quot;On your handout, write:</p><ol><li>One technique you&#39;ll practice this week</li><li>When/where you&#39;ll practice it</li><li>How you&#39;ll track your progress&quot;</li></ol><p><strong>Resources:</strong></p><ul><li>Hand out summary sheet</li><li>Share website: carreau.app</li><li>Recommend starting module: <a href="/en/education/the-zone/">The Zone</a></li></ul><p><strong>Closing Circle:</strong> &quot;One word to describe how you&#39;re feeling right now.&quot;</p><p><strong>Final Words:</strong> &quot;Mental training is a skill like any other - it takes practice. Start small, be patient with yourself, and notice what changes. Thank you for your openness today.&quot;</p><hr><h3 id="facilitator-tips" tabindex="-1">Facilitator Tips <a class="header-anchor" href="#facilitator-tips" aria-label="Permalink to &quot;Facilitator Tips&quot;">​</a></h3><h4 id="managing-difficult-situations" tabindex="-1">Managing Difficult Situations <a class="header-anchor" href="#managing-difficult-situations" aria-label="Permalink to &quot;Managing Difficult Situations&quot;">​</a></h4><p><strong>If someone dominates:</strong></p><ul><li>&quot;Thank you [name]. Let&#39;s hear from others.&quot;</li><li>Use structured turn-taking</li></ul><p><strong>If someone is resistant:</strong></p><ul><li>Don&#39;t argue</li><li>&quot;That&#39;s a valid perspective. What do others think?&quot;</li><li>Align with their concern</li></ul><p><strong>If someone gets emotional:</strong></p><ul><li>Normalize it</li><li>&quot;This touches something real. Thank you for sharing.&quot;</li><li>Don&#39;t try to fix</li></ul><p><strong>If discussion stalls:</strong></p><ul><li>Use specific prompts</li><li>Share your own example</li><li>Move to an exercise</li></ul><h4 id="energy-management" tabindex="-1">Energy Management <a class="header-anchor" href="#energy-management" aria-label="Permalink to &quot;Energy Management&quot;">​</a></h4><p><strong>High energy:</strong> Use exercises and movement <strong>Low energy:</strong> Ask provocative questions <strong>Scattered:</strong> Bring back to structure <strong>Tense:</strong> Use humor or break</p><h3 id="post-session" tabindex="-1">Post-Session <a class="header-anchor" href="#post-session" aria-label="Permalink to &quot;Post-Session&quot;">​</a></h3><p><strong>Follow-Up:</strong></p><ul><li>Send summary email within 24 hours</li><li>Include links to resources</li><li>Offer to answer questions</li><li>Schedule optional follow-up session</li></ul><p><strong>Self-Reflection:</strong></p><ul><li>What worked well?</li><li>What would you change?</li><li>What surprised you?</li><li>What did you learn?</li></ul>',118)),n(f),h[5]||(h[5]=r('<hr><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><ul><li><a href="/en/mental-journey/materials#participant-guide">Participant Guide</a></li><li><a href="/en/mental-journey/materials#facilitator-slides">Facilitator Slides</a></li><li><a href="/en/mental-journey/materials#summary-sheet">Summary Sheet</a></li><li><a href="/en/mental-journey/materials#exercise-worksheets">Exercise Worksheets</a></li></ul><hr><div class="tip custom-block"><p class="custom-block-title">Ready to Facilitate?</p><ol><li>Review this guide thoroughly</li><li>Download materials</li><li>Practice the exercises yourself</li><li>Schedule your session</li><li>Trust the process</li></ol></div>',5))])}]]);export{h as __pageData,p as default};
